package app.vpslabs.dashboard;
import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;import org.json.JSONObject;
public class LabsStorageWidget extends AppWidgetProvider{
 @Override public void onEnabled(Context c){WidgetHttp.scheduleAutoRefresh(c);}@Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if("app.vpslabs.dashboard.REFRESH_WIDGET".equals(i.getAction())){int id=i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);if(id!=AppWidgetManager.INVALID_APPWIDGET_ID)update(c,AppWidgetManager.getInstance(c),id);}}@Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){WidgetHttp.scheduleAutoRefresh(c);for(int id:ids)update(c,m,id);}
 static void update(final Context c,final AppWidgetManager m,final int id){RemoteViews v=views(c,"—","—","—","Memuat kapasitas…");bind(c,v,id);m.updateAppWidget(id,v);new Thread(new Runnable(){public void run(){updateSync(c,m,id);}}).start();}
 static void updateSync(Context c,AppWidgetManager m,int id){String disk="—",used="—",free="—",meta;try{JSONObject d=WidgetHttp.get(c,"/api/overview");disk=WidgetHttp.percent(d.optDouble("disk",0))+"%";long total=d.optLong("disk_total",0),u=d.optLong("disk_used",0);used=size(u);free=size(Math.max(0,total-u));meta=WidgetHttp.updatedNow();}catch(Exception e){meta=WidgetHttp.errorText(e);}RemoteViews v=views(c,disk,used,free,meta);bind(c,v,id);m.updateAppWidget(id,v);}private static RemoteViews views(Context c,String disk,String used,String free,String meta){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_storage);v.setTextViewText(R.id.wd_title,WidgetHttp.brand(c));v.setTextViewText(R.id.wd_percent,disk);v.setTextViewText(R.id.wd_used,used);v.setTextViewText(R.id.wd_free,free);v.setTextViewText(R.id.wd_meta,meta);return v;}private static String size(long b){if(b<=0)return"—";double gb=b/1073741824.0;return(Math.round(gb*10)/10.0)+" GB";}private static void bind(Context c,RemoteViews v,int id){v.setOnClickPendingIntent(R.id.wd_root,WidgetHttp.openPage(c,"storage",23));v.setOnClickPendingIntent(R.id.wd_refresh,WidgetHttp.refresh(c,LabsStorageWidget.class,id,2300));}}
